def find_smallest_a_correct(n):
    for a in range(1, n):
        d = n - 1 - a
        # Condition for a d-regular graph on n vertices to have no perfect matching:
        # there exists s such that c(G-S) >= s+2 and d <= n_i - 1 + s for all i.
        # To maximize the possibility, we pick c = s+2 and all n_i to be as equal as possible.
        # So we need (s+2)(d + 1 - s) <= n - s.
        for s in range(n // 2 + 1):
            c = s + 2
            if c * (d + 1 - s) <= n - s:
                # Additional condition for d-regular graph existence:
                # d*n must be even and d < n.
                if (d * n) % 2 == 0:
                    return a
    return None

for n in range(4, 10, 2):
    print(f"n={n}: {find_smallest_a_correct(n)}")

